const compareNumbers = (
  a: number,
  b: number,
  direction: SortDirection,
): number => (direction === "desc" ? b - a : a - b);

const compareStrings = (
  a: string,
  b: string,
  direction: SortDirection,
): number => {
  const comparison = a.localeCompare(b, undefined, { sensitivity: "base" });
  return direction === "desc" ? -comparison : comparison;
};

const getSortableTitle = (result: SearchResult): string =>
  stripTypePrefix(result.title);

const getCreatedTime = (result: SearchResult): number =>
  Number(result.createdAt) || 0;

export const isNonDefaultSort = (sort: SortConfig): boolean =>
  sort.field !== DEFAULT_SORT_CONFIG.field ||
  sort.direction !== DEFAULT_SORT_CONFIG.direction;

export const sortSearchResults = ({
  scoredResults,
  sort,
}: {
  scoredResults: ScoredSearchResult[];
  sort: SortConfig;
}): SearchResult[] => {
  const sorted = [...scoredResults];

  sorted.sort((aEntry, bEntry) => {
    const a = aEntry.result;
    const b = bEntry.result;
    let comparison = 0;

    switch (sort.field) {
      case "relevance":
        if (aEntry.source !== bEntry.source) {
          comparison = aEntry.source === "semantic" ? -1 : 1;
          break;
        }
        comparison = compareNumbers(aEntry.score, bEntry.score, sort.direction);
        break;
      case "alphabetical":
        comparison = compareStrings(
          getSortableTitle(a),
          getSortableTitle(b),
          sort.direction,
        );
        break;
      case "dateCreated":
        comparison = compareNumbers(
          getCreatedTime(a),
          getCreatedTime(b),
          sort.direction,
        );
        break;
      case "author": {
        const aAuthor = a.authorName.trim();
        const bAuthor = b.authorName.trim();
        if (!aAuthor && !bAuthor) comparison = 0;
        else if (!aAuthor) comparison = 1;
        else if (!bAuthor) comparison = -1;
        else comparison = compareStrings(aAuthor, bAuthor, sort.direction);
        break;
      }
    }

    return comparison || a.uid.localeCompare(b.uid);
  });

  return sorted.map((entry) => entry.result);
};

export const searchDiscourseNodesWithMiniSearch = ({
  miniSearch,
  allResults,
  searchTerm,
  typeFilter,
}: {
  miniSearch: MiniSearch<MiniSearchDocument>;
  allResults: SearchResult[];
  searchTerm: string;
  typeFilter?: string[];
}): ScoredSearchResult[] => {
  const resultsByUid = new Map(
    allResults.map((result) => [result.uid, result]),
  );
  const allowedTypes = typeFilter?.length ? new Set(typeFilter) : null;

  return miniSearch
    .search(searchTerm, {
      fields: ["title", "nodeTypeLabel"],
      ...DISCOURSE_NODE_MINI_SEARCH_OPTIONS,
      filter: allowedTypes
        ? (result) => allowedTypes.has(String(result.type))
        : undefined,
    })
    .filter((result) => result.score > DISCOURSE_NODE_MIN_SEARCH_SCORE)
    .slice(0, MAX_RESULTS)
    .map((result) => {
      const searchResult = resultsByUid.get(String(result.id));
      if (!searchResult) return null;
      return {
        result: searchResult,
        score: result.score,
        source: "miniSearch",
      };
    })
    .filter((entry): entry is ScoredSearchResult => !!entry);
};

export const runRoamSemanticSearch = async ({
  nodeTypes,
  query,
}: {
  nodeTypes: DiscourseNode[];
  query: string;
}): Promise<AdminSearchProviderPayload> => {
  const trimmedQuery = query.trim();
  const matchers = getDiscourseNodeFormatMatchers(nodeTypes);
  if (!trimmedQuery || !matchers.length) {
    return {
      rawResults: [],
      rawResultCount: 0,
      filteredResults: [],
      filteredResultCount: 0,
    };
  }

  if (!window.roamAlphaAPI.data.semanticSearchEnabled()) {
    throw new Error("Roam semantic search is not enabled.");
  }

  const hits = (await window.roamAlphaAPI.data.async.semanticSearch({
    "search-str": trimmedQuery,
    "hide-code-blocks": false,
    "search-blocks": false,
    "search-pages": true,
    k: ROAM_SEMANTIC_SEARCH_RESULT_LIMIT,
  })) as RoamSemanticSearchHit[];
  const pageHits = hits.filter((hit) => hit.type === "page");

  const titlesByUid = await pullPageTitlesByUid(
    pageHits.map((hit) => hit.uid || ""),
  );

  const rawResults = pageHits.map((hit, index) => {
    const uid = hit.uid || "";
    const title = uid ? titlesByUid[uid] : undefined;
    return toResultItem({
      uid,
      text:
        title ||
        hit.title ||
        hit.text ||
        hit.string ||
        hit.content ||
        (uid ? `Untitled hit ${uid}` : `Untitled hit ${index + 1}`),
      score: hit.score,
      source: hit.type || "unknown",
    });
  });

  const filteredResults = filterResultsToDiscourseNodeTitles({
    matchers,
    results: rawResults,
  });

  return {
    rawResults,
    rawResultCount: pageHits.length,
    filteredResults,
    filteredResultCount: filteredResults.length,
    note:
      `.semanticSearch returned ${pageHits.length}/${ROAM_SEMANTIC_SEARCH_RESULT_LIMIT} page hits; ` +
      `${hits.length - pageHits.length} non-page hits were discarded; ` +
      `${filteredResults.length} matched discourse node page-title formats.`,
  };
};

